//! The compiled architecture and the saved weights must be made by the same revision. The weights
//! are saved by `craft-ai-burn-setup` under a cache key that includes its revision string, and the
//! architecture is generated by `tools/burn/generate_sam21.py` with its own. If one is bumped and
//! the other is not, saved weights made for an older architecture would be loaded by a newer one.

/// The two strings are the same, so bumping one without the other fails here.
#[test]
fn the_architecture_and_the_saved_weights_share_one_revision() {
    let setup = include_str!("../../ai-burn-setup/src/sam21.rs");
    let line = format!(
        "const REVISION: &str = \"{}\";",
        craft_ai_engine_burn::ARCHITECTURE_REVISION
    );
    assert!(
        setup.contains(&line),
        "bump the revision in tools/burn/generate_sam21.py and crates/ai-burn-setup/src/sam21.rs together, then regenerate"
    );
}

/// The generator script states the same revision, so a regeneration cannot stamp another one.
#[test]
fn the_generator_script_states_the_same_revision() {
    let script = include_str!("../../../tools/burn/generate_sam21.py");
    let line = format!(
        "REVISION = '{}'",
        craft_ai_engine_burn::ARCHITECTURE_REVISION
    );
    assert!(script.contains(&line));
}
